"""Tokenizer, syntax tree, and recursive-descent parser for SELECT queries."""

import re

from ._errors import QueryError

KEYWORDS = frozenset("""
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
""".split())

AGGREGATES = frozenset(["COUNT", "SUM", "AVG", "MIN", "MAX"])

COMPARISONS = frozenset(["=", "!=", "<>", "<", "<=", ">", ">="])


# --- Tokens ---------------------------------------------------------------

class Token:
    __slots__ = ("kind", "text", "value", "start", "end")

    def __init__(self, kind, text, value, start, end):
        self.kind = kind    # "int", "dec", "str", "name", "qname", "op", "eof"
        self.text = text    # source text
        self.value = value  # parsed value: number, string contents, name
        self.start = start
        self.end = end

    def is_keyword(self, *words):
        return self.kind == "name" and self.value.upper() in words

    def is_op(self, *ops):
        return self.kind == "op" and self.text in ops

    def describe(self):
        return "end of query" if self.kind == "eof" else repr(self.text)


_TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<dec>[0-9]+\.[0-9]*|\.[0-9]+)
  | (?P<int>[0-9]+)
  | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<str>'(?:[^']|'')*')
  | (?P<qname>"(?:[^"]|"")*")
  | (?P<op><=|>=|<>|!=|\|\||[=<>+\-*/(),;])
""", re.VERBOSE)


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if m is None:
            ch = sql[pos]
            if ch in "'\"":
                raise QueryError(f"unterminated quoted text at position {pos}")
            raise QueryError(f"unexpected character {ch!r} at position {pos}")
        kind, text = m.lastgroup, m.group()
        start, pos = pos, m.end()
        if kind == "ws":
            continue
        if kind in ("int", "dec") and pos < len(sql) and (sql[pos].isalnum() or sql[pos] in "_."):
            raise QueryError(f"malformed number at position {start}")
        if kind == "int":
            value = int(text)
        elif kind == "dec":
            value = float(text)
        elif kind == "str":
            value = text[1:-1].replace("''", "'")
        elif kind == "qname":
            value = text[1:-1].replace('""', '"')
        else:
            value = text
        tokens.append(Token(kind, text, value, start, pos))
    tokens.append(Token("eof", "", None, len(sql), len(sql)))
    return tokens


# --- Syntax tree ----------------------------------------------------------

class Node:
    """Base expression node.

    ``span`` is the node's (start, end) offsets in the query text, and
    ``parenthesized`` is set when the node was written inside parentheses
    (in which case the span includes them).
    """

    span = (0, 0)
    parenthesized = False

    def children(self):
        return ()


class Literal(Node):
    def __init__(self, value):
        self.value = value


class Name(Node):
    def __init__(self, name):
        self.name = name
        self.index = None  # column index, set during resolution


class Unary(Node):
    def __init__(self, op, operand):
        self.op = op  # "-" or "NOT"
        self.operand = operand

    def children(self):
        return (self.operand,)


class Binary(Node):
    def __init__(self, op, left, right):
        self.op = op  # arithmetic, comparison, "||", "AND", or "OR"
        self.left = left
        self.right = right

    def children(self):
        return (self.left, self.right)


class IsNull(Node):
    def __init__(self, operand, negated):
        self.operand = operand
        self.negated = negated

    def children(self):
        return (self.operand,)


class In(Node):
    def __init__(self, operand, items, negated):
        self.operand = operand
        self.items = items
        self.negated = negated

    def children(self):
        return (self.operand,) + tuple(self.items)


class Between(Node):
    def __init__(self, operand, low, high, negated):
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated

    def children(self):
        return (self.operand, self.low, self.high)


class Like(Node):
    def __init__(self, operand, pattern, negated):
        self.operand = operand
        self.pattern = pattern
        self.negated = negated

    def children(self):
        return (self.operand, self.pattern)


class Call(Node):
    def __init__(self, name, args, star=False):
        self.name = name.upper()
        self.args = args
        self.star = star  # COUNT(*)

    @property
    def is_aggregate(self):
        return self.name in AGGREGATES

    def children(self):
        return tuple(self.args)


class Column:
    """An item in the SELECT list."""

    def __init__(self, expr, alias, text):
        self.expr = expr
        self.alias = alias
        self.text = text  # the expression as written


class OrderItem:
    def __init__(self, expr, descending):
        self.expr = expr
        self.descending = descending


class Query:
    def __init__(self):
        self.distinct = False
        self.columns = None  # None for SELECT *
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []
        self.limit = None
        self.offset = 0


# --- Parser ---------------------------------------------------------------

def parse(sql):
    return _Parser(sql).parse_query()


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # Token helpers

    def peek(self, offset=0):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        token = self.tokens[self.pos]
        if token.kind != "eof":
            self.pos += 1
        return token

    def prev_end(self):
        return self.tokens[self.pos - 1].end

    def error(self, expected):
        token = self.peek()
        return QueryError(f"syntax error at position {token.start}: "
                          f"expected {expected}, got {token.describe()}")

    def accept_keyword(self, *words):
        if self.peek().is_keyword(*words):
            return self.advance()
        return None

    def expect_keyword(self, word):
        if not self.accept_keyword(word):
            raise self.error(word)

    def accept_op(self, *ops):
        if self.peek().is_op(*ops):
            return self.advance()
        return None

    def expect_op(self, op):
        if not self.accept_op(op):
            raise self.error(repr(op))

    def at_name(self):
        token = self.peek()
        return token.kind == "qname" or (
            token.kind == "name" and token.value.upper() not in KEYWORDS)

    def expect_name(self):
        if not self.at_name():
            raise self.error("a name")
        return self.advance().value

    def expect_integer(self):
        if self.peek().kind != "int":
            raise self.error("an integer")
        return self.advance().value

    # Query structure

    def parse_query(self):
        q = Query()
        self.expect_keyword("SELECT")
        q.distinct = bool(self.accept_keyword("DISTINCT"))
        if not self.accept_op("*"):
            q.columns = [self.parse_column()]
            while self.accept_op(","):
                q.columns.append(self.parse_column())
        self.expect_keyword("FROM")
        q.table = self.expect_name()
        if self.accept_keyword("WHERE"):
            q.where = self.parse_expr()
        if self.accept_keyword("GROUP"):
            self.expect_keyword("BY")
            q.group_by = self.parse_list(self.parse_expr)
        if self.accept_keyword("HAVING"):
            q.having = self.parse_expr()
        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            q.order_by = self.parse_list(self.parse_order_item)
        if self.accept_keyword("LIMIT"):
            q.limit = self.expect_integer()
            if self.accept_keyword("OFFSET"):
                q.offset = self.expect_integer()
        self.accept_op(";")
        if self.peek().kind != "eof":
            raise self.error("end of query")
        return q

    def parse_list(self, parse_item):
        items = [parse_item()]
        while self.accept_op(","):
            items.append(parse_item())
        return items

    def parse_column(self):
        expr = self.parse_expr()
        text = self.sql[expr.span[0]:expr.span[1]]
        alias = None
        if self.accept_keyword("AS"):
            alias = self.expect_name()
        elif self.at_name():
            alias = self.advance().value
        return Column(expr, alias, text)

    def parse_order_item(self):
        expr = self.parse_expr()
        descending = False
        token = self.accept_keyword("ASC", "DESC")
        if token:
            descending = token.value.upper() == "DESC"
        return OrderItem(expr, descending)

    # Expressions, lowest precedence first

    def finish(self, node, start):
        node.span = (start, self.prev_end())
        return node

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        start = self.peek().start
        left = self.parse_and()
        while self.accept_keyword("OR"):
            left = self.finish(Binary("OR", left, self.parse_and()), start)
        return left

    def parse_and(self):
        start = self.peek().start
        left = self.parse_not()
        while self.accept_keyword("AND"):
            left = self.finish(Binary("AND", left, self.parse_not()), start)
        return left

    def parse_not(self):
        start = self.peek().start
        if self.accept_keyword("NOT"):
            return self.finish(Unary("NOT", self.parse_not()), start)
        return self.parse_comparison()

    def parse_comparison(self):
        start = self.peek().start
        left = self.parse_additive()
        while True:
            token = self.peek()
            if token.kind == "op" and token.text in COMPARISONS:
                self.advance()
                op = "!=" if token.text == "<>" else token.text
                node = Binary(op, left, self.parse_additive())
            elif token.is_keyword("IS"):
                self.advance()
                negated = bool(self.accept_keyword("NOT"))
                self.expect_keyword("NULL")
                node = IsNull(left, negated)
            elif token.is_keyword("IN", "BETWEEN", "LIKE") or (
                    token.is_keyword("NOT")
                    and self.peek(1).is_keyword("IN", "BETWEEN", "LIKE")):
                negated = bool(self.accept_keyword("NOT"))
                word = self.advance().value.upper()
                if word == "IN":
                    self.expect_op("(")
                    items = self.parse_list(self.parse_expr)
                    self.expect_op(")")
                    node = In(left, items, negated)
                elif word == "BETWEEN":
                    low = self.parse_additive()
                    self.expect_keyword("AND")
                    node = Between(left, low, self.parse_additive(), negated)
                else:
                    node = Like(left, self.parse_additive(), negated)
            else:
                return left
            left = self.finish(node, start)

    def parse_additive(self):
        start = self.peek().start
        left = self.parse_multiplicative()
        while True:
            token = self.accept_op("+", "-", "||")
            if not token:
                return left
            right = self.parse_multiplicative()
            left = self.finish(Binary(token.text, left, right), start)

    def parse_multiplicative(self):
        start = self.peek().start
        left = self.parse_unary()
        while True:
            token = self.accept_op("*", "/")
            if not token:
                return left
            right = self.parse_unary()
            left = self.finish(Binary(token.text, left, right), start)

    def parse_unary(self):
        start = self.peek().start
        if self.accept_op("-"):
            return self.finish(Unary("-", self.parse_unary()), start)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        start = token.start
        if token.kind in ("int", "dec", "str"):
            self.advance()
            return self.finish(Literal(token.value), start)
        if token.is_keyword("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[token.value.upper()]
            return self.finish(Literal(value), start)
        if token.is_op("("):
            self.advance()
            node = self.parse_expr()
            self.expect_op(")")
            node.parenthesized = True
            return self.finish(node, start)
        if self.at_name():
            self.advance()
            if token.kind == "name" and self.accept_op("("):
                return self.finish(self.parse_call(token.value), start)
            return self.finish(Name(token.value), start)
        raise self.error("an expression")

    def parse_call(self, name):
        # The opening parenthesis has been consumed.
        if self.accept_op("*"):
            self.expect_op(")")
            if name.upper() != "COUNT":
                raise QueryError(f"{name}(*) is not allowed; only COUNT(*)")
            return Call(name, [], star=True)
        args = []
        if not self.accept_op(")"):
            args = self.parse_list(self.parse_expr)
            self.expect_op(")")
        return Call(name, args)

