def _aggregate(name, values):
    if name == "COUNT":
        return sum(1 for v in values if v is not None)
    values = [v for v in values if v is not None]
    if not values:
        return None
    if name in ("SUM", "AVG"):
        total = 0
        for v in values:
            total = total + _number(v, f"argument of {name}")
        return total / len(values) if name == "AVG" else total
    best = values[0]
    sign = -1 if name == "MIN" else 1
    for v in values[1:]:
        if _compare(v, best) * sign > 0:
            best = v
    return best


# --- Evaluation -----------------------------------------------------------

def _evaluate(node, row, group=None):
    """Evaluate ``node`` against ``row``.

    In a grouped query ``group`` is the list of the group's rows and ``row``
    is its first row (or None for an empty group).
    """
    t = type(node)
    if t is Literal:
        return node.value
    if t is Name:
        return row[node.index]
    if t is Binary:
        op = node.op
        left = _evaluate(node.left, row, group)
        right = _evaluate(node.right, row, group)
        if op == "AND":
            return _and(left, right)
        if op == "OR":
            return _or(left, right)
        if op == "||":
            if left is None or right is None:
                return None
            return _text(left) + _text(right)
        if op in _COMPARE_OPS:
            return _comparison(op, left, right)
        return _arithmetic(op, left, right)
    if t is Unary:
        value = _evaluate(node.operand, row, group)
        if node.op == "NOT":
            return _not(value)
        if value is None:
            return None
        return -_number(value, "operand of unary -")
    if t is IsNull:
        return (_evaluate(node.operand, row, group) is None) != node.negated
    if t is In:
        value = _evaluate(node.operand, row, group)
        items = [_evaluate(item, row, group) for item in node.items]
        if value is None:
            result = None
        else:
            found = any(_compare(value, item) == 0 for item in items if item is not None)
            result = True if found else (None if None in items else False)
        return _not(result) if node.negated else result
    if t is Between:
        value = _evaluate(node.operand, row, group)
        low = _evaluate(node.low, row, group)
        high = _evaluate(node.high, row, group)
        result = _and(_comparison("<=", low, value), _comparison("<=", value, high))
        return _not(result) if node.negated else result
    if t is Like:
        value = _evaluate(node.operand, row, group)
        pattern = _evaluate(node.pattern, row, group)
        if value is None or pattern is None:
            return None
        _string(value, "operand of LIKE")
        _string(pattern, "pattern of LIKE")
        result = _like_regex(pattern).fullmatch(value) is not None
        return result != node.negated
    if t is Call:
        if node.is_aggregate:
            if node.star:
                return len(group)
            arg = node.args[0]
            return _aggregate(node.name, [_evaluate(arg, r) for r in group])
        if node.name == "COALESCE":
            for arg in node.args:
                value = _evaluate(arg, row, group)
                if value is not None:
                    return value
            return None
        args = [_evaluate(arg, row, group) for arg in node.args]
        if None in args:
            return None
        return _SCALARS[node.name][2](args)
    raise AssertionError(f"unknown node {node!r}")


def _condition(node, row, group=None):
    """Whether a WHERE or HAVING condition is TRUE."""
    return _boolean(_evaluate(node, row, group), "condition") is True


# --- Checking -------------------------------------------------------------

def _walk(node):
    yield node
    for child in node.children():
        yield from _walk(child)


def _has_aggregate(node):
    return any(isinstance(n, Call) and n.is_aggregate for n in _walk(node))


class _Resolver:
    """Resolves column names and checks function calls."""

    def __init__(self, header):
        self.header = header
        self.indexes = {}
        for i, name in enumerate(header):
            self.indexes.setdefault(name.lower(), []).append(i)

    def resolve(self, node, clause, in_aggregate=False):
        if isinstance(node, Name):
            matches = self.indexes.get(node.name.lower(), [])
            if not matches:
                raise QueryError(f"no such column: {node.name}")
            if len(matches) > 1:
                raise QueryError(f"ambiguous column name: {node.name}")
            node.index = matches[0]
            return
        if isinstance(node, Call):
            self.check_call(node, clause, in_aggregate)
            in_aggregate = in_aggregate or node.is_aggregate
        for child in node.children():
            self.resolve(child, clause, in_aggregate)

    @staticmethod
    def check_call(node, clause, in_aggregate):
        name, count = node.name, len(node.args)
        if node.is_aggregate:
            if clause in ("WHERE", "GROUP BY"):
                raise QueryError(f"aggregate {name} is not allowed in {clause}")
            if in_aggregate:
                raise QueryError(f"aggregate {name} cannot be nested in another aggregate")
            if not node.star and count != 1:
                raise QueryError(f"{name} takes 1 argument, got {count}")
        elif name == "COALESCE":
            if count < 1:
                raise QueryError("COALESCE takes at least 1 argument")
        elif name in _SCALARS:
            lo, hi, _ = _SCALARS[name]
            if not lo <= count <= hi:
                expected = f"{lo}" if lo == hi else f"{lo} or {hi}"
                raise QueryError(f"{name} takes {expected} argument(s), got {count}")
        else:
            raise QueryError(f"unknown function: {name}")


def _shape(node):
    """A structural key for comparing expressions with GROUP BY items."""
    if isinstance(node, Literal):
        return ("Literal", _key(node.value))
    if isinstance(node, Name):
        return ("Name", node.index)
    attrs = tuple(getattr(node, a, None) for a in ("op", "name", "negated", "star"))
    return (type(node).__name__, attrs, tuple(_shape(c) for c in node.children()))


def _check_grouped(node, group_shapes, clause):
    """Check that ``node`` only uses columns via GROUP BY items or aggregates."""
    if _shape(node) in group_shapes:
        return
    if isinstance(node, Call) and node.is_aggregate:
        return
    if isinstance(node, Name):
        raise QueryError(f"column {node.name} in {clause} must appear in GROUP BY "
                         f"or be used in an aggregate")
    for child in node.children():
        _check_grouped(child, group_shapes, clause)


# --- Execution ------------------------------------------------------------

def _execute(q, directory):
    header, rows = _load_table(directory, q.table)
    resolver = _Resolver(header)

    if q.columns is None:
        columns = []
        for i, name in enumerate(header):
            node = Name(name)
            node.index = i
            columns.append(Column(node, None, name))
    else:
        columns = q.columns
        for col in columns:
            resolver.resolve(col.expr, "SELECT")

    names = []
    for col in columns:
        expr = col.expr
        if col.alias is not None:
            names.append(col.alias)
        elif isinstance(expr, Name) and not expr.parenthesized:
            names.append(header[expr.index])
        else:
            names.append(col.text)

    if q.where is not None:
        resolver.resolve(q.where, "WHERE")
    for expr in q.group_by:
        resolver.resolve(expr, "GROUP BY")
    if q.having is not None:
        resolver.resolve(q.having, "HAVING")

    # Each ORDER BY item is ("output", column index) or ("expr", node).
    order = []
    for item in q.order_by:
        expr = item.expr
        target = None
        if isinstance(expr, Name) and not expr.parenthesized:
            lowered = expr.name.lower()
            target = next((i for i, n in enumerate(names) if n.lower() == lowered), None)
        elif (isinstance(expr, Literal) and not expr.parenthesized
              and type(expr.value) is int):
            if not 1 <= expr.value <= len(columns):
                raise QueryError(f"ORDER BY position {expr.value} is out of range "
                                 f"(there are {len(columns)} output columns)")
            target = expr.value - 1
        if target is None:
            resolver.resolve(expr, "ORDER BY")
            order.append(("expr", expr, item.descending))
        else:
            order.append(("output", target, item.descending))

    order_exprs = [target for kind, target, _ in order if kind == "expr"]
    having = [q.having] if q.having is not None else []
    grouped = bool(q.group_by) or any(
        _has_aggregate(e) for e in [c.expr for c in columns] + having + order_exprs)
    if grouped:
        shapes = {_shape(e) for e in q.group_by}
        for col in columns:
            _check_grouped(col.expr, shapes, "SELECT")
        for expr in having:
            _check_grouped(expr, shapes, "HAVING")
        for expr in order_exprs:
            _check_grouped(expr, shapes, "ORDER BY")

    if q.where is not None:
        rows = [r for r in rows if _condition(q.where, r)]

    # Build (output values, sort keys) for each result row.
    def project(row, group=None):
        values = tuple(_evaluate(c.expr, row, group) for c in columns)
        keys = tuple(values[target] if kind == "output" else _evaluate(target, row, group)
                     for kind, target, _ in order)
        return values, keys

    results = []
    if grouped:
        shapes = {_shape(e) for e in q.group_by}
        for col in columns:
            _check_grouped(col.expr, shapes, "SELECT")
        if q.having is not None:
            _check_grouped(q.having, shapes, "HAVING")
        for expr in order_exprs:
            _check_grouped(expr, shapes, "ORDER BY")

        if q.group_by:
            groups = {}
            for r in rows:
                key = _row_key(_evaluate(e, r) for e in q.group_by)
                groups.setdefault(key, []).append(r)
            groups = list(groups.values())
        else:
            groups = [rows]
        for group in groups:
            first = group[0] if group else None
            if q.having is None or _condition(q.having, first, group):
                results.append(project(first, group))
    else:
        for r in rows:
            if q.having is None or _condition(q.having, r):
                results.append(project(r))

    if q.distinct:
        seen = set()
        unique = []
        for values, keys in results:
            key = _row_key(values)
            if key not in seen:
                seen.add(key)
                unique.append((values, keys))
        results = unique

    if order:
        directions = [descending for _, _, descending in order]

        def compare(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                if x is None and y is None:
                    c = 0
                elif x is None:
                    c = -1
                elif y is None:
                    c = 1
                else:
                    c = _compare(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(compare))

    results = results[q.offset:]
    if q.limit is not None:
        results = results[:q.limit]
    return Result(names, [values for values, _ in results])

